// src/App.js

import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";

// import หน้าต่าง ๆ ที่คุณมีอยู่ เช่น
// import Home from "./pages/Home";
// import About from "./pages/About";

function App() {
  return (
    <Router>
      <div>
        {/* ถ้าคุณมี header/footer อื่น ๆ ใส่ตรงนี้ได้ */}
        <Routes>
          {/* เพิ่มเส้นทาง (Route) ไปยังแต่ละหน้าที่คุณสร้าง */}
          {
          <Route path="/" element={<Home />} />
          }
        </Routes>
      </div>
    </Router>
  );
}

export default App;
